 insert into public.visual_tutorials(challenge_id,lesson_id,title,intro,palette,final_image,tips,published) values((r->>'challenge_id')::integer,r->>'lesson_id',r->'payload'->>'title',r->'payload'->>'intro',r->'payload'->'palette',r->'payload'->>'final_image',r->'payload'->>'tips',true) on conflict do nothing returning id into tid;
 insert into public.tutorial_steps(tutorial_id,position,title,description,image,type,tip) select tid,ordinality::integer,value->>'title',value->>'description',value->>'image',value->>'type',coalesce(value->>'tip','') from jsonb_array_elements(r->'payload'->'steps') with ordinality;
